        const dropTable = initData?.openableLootDropMap?.[containerHrid];
        if (!dropTable) return 0;

        let payout = 0;
        for (const drop of dropTable) {
            if (drop.dropRate !== 1) continue;
            payout += priceRealizedDrop(drop.itemHrid, drop.minCount || 0) || 0;
        }

        return payout;
